private void HighlightBoundingBox(double[] bb)
        {
            double[][] corners = new double[][]
            {
                new double[] { bb[0], bb[2], bb[4] },
                new double[] { bb[1], bb[2], bb[4] },
                new double[] { bb[1], bb[3], bb[4] },
                new double[] { bb[0], bb[3], bb[4] },
                new double[] { bb[0], bb[2], bb[5] },
                new double[] { bb[1], bb[2], bb[5] },
                new double[] { bb[1], bb[3], bb[5] },
                new double[] { bb[0], bb[3], bb[5] }
            };
            // One connected traversal covers all twelve edges; repeated edges overlap exactly.
            int[] path = new int[] { 0, 1, 2, 3, 0, 4, 5, 6, 7, 4, 5, 1, 2, 6, 7, 3 };
            double[][] lineCoor = new double[path.Length][];
            for (int i = 0; i < path.Length; i++) lineCoor[i] = corners[path[i]];
            //
            _controller.HighlightConnectedLines(lineCoor);
            _controller.HighlightNodes(new double[][] { GetBoundingBoxCenter(bb) });
        }
private double[] GetBoundingBoxCenter(double[] bb)
        {
            return new double[] { 0.5 * (bb[0] + bb[1]), 0.5 * (bb[2] + bb[3]), 0.5 * (bb[4] + bb[5]) };
        }
public void TwoNodesPicked(int nodeId1, int nodeId2)
        {
            if (Form_WriteDataToOutput != null)
            {
                string data;
                Vec3D baseV1 = new Vec3D(_controller.GetNode(nodeId1, false).Coor);
                Vec3D baseV2 = new Vec3D(_controller.GetNode(nodeId2, false).Coor);
                Vec3D baseD = baseV2 - baseV1;
                string lenUnit = _controller.GetLengthUnit();
                string lenUnitInBrackets = string.Format("[{0}]", lenUnit);
                //
                Form_WriteDataToOutput("");
                data = string.Format(
                    "{0,16}{1,8}{2,16}{3,16}, {4,16}", "Distance".PadRight(16), "[/]", "id1, id2:", nodeId1, nodeId2);
                Form_WriteDataToOutput(data);
                data = string.Format("{0,16}{1,8}{2,16}{3,16}, {4,16}, {5,16}, {6,16}",
                                     "Base".PadRight(16), lenUnitInBrackets, "dx, dy, dz, D:",
                                     FormatQueryValue(baseD.X), FormatQueryValue(baseD.Y), FormatQueryValue(baseD.Z),
                                     FormatQueryValue(baseD.Len));
                Form_WriteDataToOutput(data);
                //
                if (_controller.CurrentView == ViewGeometryModelResults.Results)
                {
                    Vec3D trueScaledV1 = new Vec3D(_controller.GetScaledNode(1, nodeId1, false).Coor);
                    Vec3D trueScaledV2 = new Vec3D(_controller.GetScaledNode(1, nodeId2, false).Coor);
                    Vec3D trueScaledD = trueScaledV2 - trueScaledV1;
                    Vec3D delta = trueScaledD - baseD;
                    //
                    data = string.Format("{0,16}{1,8}{2,16}{3,16}, {4,16}, {5,16}, {6,16}",
                                         "Deformed".PadRight(16), lenUnitInBrackets, "dx, dy, dz, D:",
                                         FormatQueryValue(trueScaledD.X), FormatQueryValue(trueScaledD.Y),
                                         FormatQueryValue(trueScaledD.Z), FormatQueryValue(trueScaledD.Len));
                    Form_WriteDataToOutput(data);
                    data = string.Format("{0,16}{1,8}{2,16}{3,16}, {4,16}, {5,16}, {6,16}",
                                         "Delta".PadRight(16), lenUnitInBrackets, "dx, dy, dz, D:",
                                         FormatQueryValue(delta.X), FormatQueryValue(delta.Y), FormatQueryValue(delta.Z),
                                         FormatQueryValue(trueScaledD.Len - baseD.Len));
                    Form_WriteDataToOutput(data);
                }
                Form_WriteDataToOutput("");
                _controller.Annotations.AddDistanceAnnotation(nodeId1, nodeId2);
            }
        }
private void ComputeAngle(int nodeId1, int nodeId2, int nodeId3)
        {
            System.Diagnostics.Debug.Write(nodeId1 + " " + nodeId2 + " " + nodeId3);
            string data;
            double angle;
            Vec3D baseV1 = new Vec3D(_controller.GetNode(nodeId1, false).Coor);
            Vec3D baseV2 = new Vec3D(_controller.GetNode(nodeId2, false).Coor);
            Vec3D baseV3 = new Vec3D(_controller.GetNode(nodeId3, false).Coor);
            //
            angle = ComputeAngle(baseV1, baseV2, baseV3, out _, out _);
            string angleUnit = StringAngleDegConverter.GetUnitAbbreviation();
            string angleUnitInBrackets = "[" + angleUnit + "]";
            //
            data = string.Format("{0,16}{1,8}{2,16}{3,16}, {4,16}, {5,16}",
                                 "Angle".PadRight(16), "[/]", "id1, id2, id3:", nodeId1, nodeId2, nodeId3);
            Form_WriteDataToOutput(data);
            data = string.Format("{0,16}{1,8}{2,16}{3,16}", "Base".PadRight(16), angleUnitInBrackets, "ϕ:",
                                 FormatQueryValue(angle));
            Form_WriteDataToOutput(data);
            //
            if (_controller.CurrentView == ViewGeometryModelResults.Results)
            {
                baseV1 = new Vec3D(_controller.GetScaledNode(1, nodeId1, false).Coor);
                baseV2 = new Vec3D(_controller.GetScaledNode(1, nodeId2, false).Coor);
                baseV3 = new Vec3D(_controller.GetScaledNode(1, nodeId3, false).Coor);
                //
                double angle2 = ComputeAngle(baseV1, baseV2, baseV3, out _, out _);
                double delta = angle2 - angle;
                //
                data = string.Format("{0,16}{1,8}{2,16}{3,16}", "Deformed".PadRight(16), angleUnitInBrackets, "ϕ:",
                                     FormatQueryValue(angle2));
                Form_WriteDataToOutput(data);
                data = string.Format("{0,16}{1,8}{2,16}{3,16}", "Delta".PadRight(16), angleUnitInBrackets, "ϕ:",
                                     FormatQueryValue(delta));
                Form_WriteDataToOutput(data);
            }
            Form_WriteDataToOutput("");
            _controller.Annotations.AddAngleAnnotation(nodeId1, nodeId2, nodeId3);
        }
private void ComputeCircle(int nodeId1, int nodeId2, int nodeId3)
        {
            // https://en.wikipedia.org/wiki/Circumscribed_circle
            string data;
            double r;
            Vec3D center;
            Vec3D axis;
            Vec3D baseV1 = new Vec3D(_controller.GetNode(nodeId1, false).Coor);
            Vec3D baseV2 = new Vec3D(_controller.GetNode(nodeId2, false).Coor);
            Vec3D baseV3 = new Vec3D(_controller.GetNode(nodeId3, false).Coor);
            //
            Vec3D.GetCircle(baseV1, baseV2, baseV3, out r, out _, out center, out axis);
            string lenUnit = _controller.GetLengthUnit();
            string lenUnitInBrackets = string.Format("[{0}]", lenUnit);
            //
            Form_WriteDataToOutput("");
            data = string.Format("{0,16}{1,8}{2,16}{3,16}, {4,16}, {5,16}",
                                 "Circle".PadRight(16), "[/]", "id1, id2, id3:", nodeId1, nodeId2, nodeId3);
            Form_WriteDataToOutput(data);
            data = string.Format("{0,16}{1,8}{2,16}{3,16}, {4,16}, {5,16}, {6,16}",
                                 "Base".PadRight(16), lenUnitInBrackets, "x, y, z, R:", FormatQueryValue(center.X),
                                 FormatQueryValue(center.Y), FormatQueryValue(center.Z), FormatQueryValue(r));
            Form_WriteDataToOutput(data);
            data = string.Format("{0,16}{1,8}{2,16}{3,16}, {4,16}, {5,16}",
                                 "Base axis".PadRight(16), lenUnitInBrackets, "x, y, z:", FormatQueryValue(axis.X),
                                 FormatQueryValue(axis.Y), FormatQueryValue(axis.Z));
            Form_WriteDataToOutput(data);
            //
            if (_controller.CurrentView == ViewGeometryModelResults.Results)
            {
                baseV1 = new Vec3D(_controller.GetScaledNode(1, nodeId1, false).Coor);
                baseV2 = new Vec3D(_controller.GetScaledNode(1, nodeId2, false).Coor);
                baseV3 = new Vec3D(_controller.GetScaledNode(1, nodeId3, false).Coor);
                //
                Vec3D.GetCircle(baseV1, baseV2, baseV3, out r, out center, out axis);
                //
                data = string.Format("{0,16}{1,8}{2,16}{3,16}, {4,16}, {5,16}, {6,16}",
                                     "Deformed".PadRight(16), lenUnitInBrackets, "x, y, z, R:",
                                     FormatQueryValue(center.X), FormatQueryValue(center.Y), FormatQueryValue(center.Z),
                                     FormatQueryValue(r));
                Form_WriteDataToOutput(data);
                data = string.Format("{0,16}{1,8}{2,16}{3,16}, {4,16}, {5,16}",
                                     "Deformed axis".PadRight(16), lenUnitInBrackets, "x, y, z:",
                                     FormatQueryValue(axis.X), FormatQueryValue(axis.Y), FormatQueryValue(axis.Z));
                Form_WriteDataToOutput(data);
            }
            Form_WriteDataToOutput("");
            _controller.Annotations.AddCircleAnnotation(nodeId1, nodeId2, nodeId3);
        }
private double ComputeAngle(Vec3D baseV1, Vec3D baseV2, Vec3D baseV3, out Vec3D p, out Vec3D axis)
        {
            Vec3D line1 = baseV1 - baseV2;
            Vec3D line2 = baseV3 - baseV2;
            //
            if (line1.Len2 > line2.Len2)  // find shorter line
            {
                p = baseV2 + line2 * 0.5;
                axis = Vec3D.CrossProduct(line2, line1);
            }
            else
            {
                p = baseV2 + line1 * 0.5;
                axis = Vec3D.CrossProduct(line1, line2);
            }
            axis.Normalize();
            line1.Normalize();
            line2.Normalize();
            //
            double angle = Math.Acos(Vec3D.DotProduct(line1, line2)) * 180 / Math.PI;
            return angle;
        }
private string FormatQueryValue(double value)
        {
            return value.ToString(_queryNumberFormat);
        }
private void UpdateQueryNumberFormat()
        {
            _queryNumberFormat = _controller.Settings.NumberFormat.GetNumberFormat();
        }
public void Highlight()
        {
            if (_coorNodesToDraw != null) _controller.HighlightNodes(_coorNodesToDraw);
        }
}
